import jinja2

def render_message(message):
    template = jinja2.Template("<p>" + message + "</p>", autoescape=False)
    return template.render(message=message)

print(render_message("<p>I'm an AI assistant</p>"))

from jinja2 import Template

def render_note(note):
    template = Template('{{ note }}', autoescape=False)
    return template.render(note=note)

